#! /bin/bash
# Replaces the reference images in expected/ with the images generated by a CI run, for all three platforms.
# Use this after a Strype release changes how things look and so makes the image tests fail.
#
# Usage (from test/):  ./update-expected-from-ci.sh RUN_ID
#
# CI uploads the generated images on every run (as images-Ubuntu, images-Windows and images-macOS), whether or not
# the comparison passed. IMPORTANT: look at the images before committing them -- they become the references, so a
# wrong render (e.g. a dialog, or the wrong project) would be treated as correct from then on.
set -e

RUN_ID="$1"
if [ -z "$RUN_ID" ]; then
  echo "Usage: $0 RUN_ID" >&2
  exit 1
fi

DOWNLOAD_DIR=$(mktemp -d)
trap 'rm -rf "$DOWNLOAD_DIR"' EXIT

for PAIR in Ubuntu:linux Windows:windows macOS:macos; do
  ARTIFACT="images-${PAIR%%:*}"
  PLATFORM="${PAIR##*:}"
  gh run download "$RUN_ID" -n "$ARTIFACT" -D "$DOWNLOAD_DIR/$ARTIFACT"
  mkdir -p "expected/$PLATFORM"
  for ACTUAL in "$DOWNLOAD_DIR/$ARTIFACT"/actual-*.png; do
    NAME=$(basename "$ACTUAL")
    cp "$ACTUAL" "expected/$PLATFORM/expected-${NAME#actual-}"
  done
  echo "Updated expected/$PLATFORM from $ARTIFACT"
done
